   '"공작 각하께서는 오늘 중요한 서신 업무가 있으셔서 나오지 못하셨습니다. 대신 사과의 말씀을 전하라 하셨습니다."',
   '아주 매끄러운 답이었다. 너무 매끄러웠다. 사과를 전하라는 말씀이 정말 있었다면 집사는 \'말씀하셨습니다\'라고 했을 것이다. {{lie|\'하셨습니다\'라는 말은 대개 아무도 하지 않은 말 뒤에 붙는다.}}'
