 s5:{place:'bedroom',season:'늦가을',age:'열 살',chLabel:CHLAB,chars:[{id:'tangie',pos:'center',expr:'smile'}],
  paras:[
   '방은 내가 상상한 것보다 따뜻했다. 벽난로에는 이미 불이 피워져 있었고, 창가에는 책상이 놓여 있었다. 서랍을 열어 보니 새 노트와 깃펜, 잉크병이 정확히 한 벌씩 들어 있었다. {{notebook|누군가 내가 글을 쓰는 아이라는 것을 미리 알고 있었던 것이다.}}',
   '그때 문이 벌컥 열렸다.',
   '"아, 죄송해요! 노크를 먼저 했어야 했는데, 짐이 너무 무거워서 팔로 열어 버렸어요!"',
   '커다란 가방을 끌어안은 소녀가 얼굴을 반쯤 내밀고 있었다. 모자 밖으로 삐져나온 머리카락이 벽난로 불빛을 받아 잘 익은 귤처럼 반짝였다. 그녀는 나를 보자마자 환하게 웃었다. 정말로, 방 안이 한 단계 밝아지는 웃음이었다.',
   '"저는 탠지예요! 오늘부터 아가씨 곁에서 시중을 들게 됐어요!"',
   '나는 듣다가 한 가지를 알아챘다. 탠지는 가방을 옮길 때마다 {{shoulder|오른쪽 어깨를 아주 조금 더 낮췄다.}} 아침부터 무언가를 많이 날랐던 사람의 자세였다. 그런데도 그녀는 한 번도 \'힘들다\'고 하지 않았다.'
  ],
  choices:[{label:'아무 말 하지 않는다',next:'s5b',flag:'keptSilent'},{label:'가방 한쪽을 같이 든다',next:'s5b',flag:'helpedBag'}]},
